// ============================================================
// Solides - Criar Colaborador (Code node)
// ------------------------------------------------------------
// Etapa do workflow "Forms de admissao" no n8n que MAPEIA os
// campos crus do formulario para o contrato da API Solides e
// dispara POST /pt-BR/api/v1/colaboradores.
//
// CONTRATO DE ENTRADA
// ------------------------------------------------------------
// Espera receber, no $input.first().json:
//
//   formulario.*   -> dados crus do form (nomes iguais aos <input>)
//   position       -> cargo, definido pelo no de validacao do RH
//   department     -> setor, idem
//   metadata       -> opcional, repassado para os proximos nos
//
// O front (script.js) NAO conhece mais o contrato da Solides.
// Toda traducao (enum por extenso, dd/mm/aaaa, prefixo de pais
// no telefone, campos achatados de endereco) acontece aqui.
//
// CONFIGURACAO DO TOKEN
// ------------------------------------------------------------
// Opcao A (rapida): trocar a string COLE_SEU_TOKEN_AQUI abaixo.
// Opcao B (recomendada): criar uma credencial Header Auth no
//   n8n (Name=Authorization, Value=Token token=<TOKEN>) e migrar
//   este Code node para um HTTP Request node que referencia a
//   credencial - o token sai do JS.
// ============================================================

const SOLIDES_ENDPOINT = 'https://app.solides.com/pt-BR/api/v1/colaboradores';
const SOLIDES_TOKEN    = 'COLE_SEU_TOKEN_AQUI';

// ------------------------------------------------------------
// Mapas de enum (form -> API Solides)
// ------------------------------------------------------------
// Os <select> do form usam values curtos por conveniencia.
// A API exige enums por extenso, capitalizados e COM acento.
// Sempre que mudar um <option> em index.html, ajustar aqui.
// ------------------------------------------------------------
const MAPA_GENERO = { M: 'Masculino', F: 'Feminino', O: null, N: null };

const MAPA_ESTADO_CIVIL = {
  solteiro:      'Solteiro',
  casado:        'Casado',
  divorciado:    'Divorciado',
  viuvo:         'Vi\u00favo',          // Viuvo com acento
  uniao_estavel: 'Uni\u00e3o Est\u00e1vel',  // Uniao Estavel com acentos
  separado:      'Divorciado'         // API nao tem 'Separado'; aproximacao semantica
};

const MAPA_ETNIA = {
  branca:        'Branca',
  preta:         'Preta',
  parda:         'Parda',
  amarela:       'Amarela',
  indigena:      'Ind\u00edgena',         // Indigena com acento
  nao_declarada: 'Outro'              // API nao tem opcao neutra
};

// schooling: nivel de escolaridade. Valores conforme contrato
// da API Solides ("Ensino X Y" por extenso, com acentos).
const MAPA_GRAU_INSTRUCAO = {
  fundamental_incompleto: 'Ensino Fundamental Incompleto',
  fundamental:            'Ensino Fundamental Completo',
  medio_incompleto:       'Ensino M\u00e9dio Incompleto',     // Medio com acento
  medio:                  'Ensino M\u00e9dio Completo',
  superior_incompleto:    'Ensino Superior Incompleto',
  superior:               'Ensino Superior Completo',
  pos:                    'P\u00f3s-Gradua\u00e7\u00e3o',     // Pos-Graduacao com acentos
  mestrado:               'Mestrado',
  doutorado:              'Doutorado'
};

// ------------------------------------------------------------
// Utilitarios de normalizacao
// ------------------------------------------------------------

// Converte data de YYYY-MM-DD (formato do <input type="date">)
// para dd/mm/aaaa exigido pela Solides.
function formatarDataBR(isoDate) {
  if (!isoDate) return null;
  const [ano, mes, dia] = String(isoDate).split('-');
  if (!ano || !mes || !dia) return null;
  return `${dia}/${mes}/${ano}`;
}

// Normaliza o celular para o formato internacional aceito pela
// Solides. A UI da Solides parseia cellPhone como E.164: o(s)
// primeiro(s) digito(s) viram codigo do pais. Um celular brasileiro
// sem o prefixo 55 acaba sendo interpretado como +1 (EUA), porque
// o '1' inicial do DDD vira o country code.
//
// Regra:
//   - 10 digitos (DDD + fixo) OU 11 digitos (DDD + movel 9 digitos)
//     -> prefixar '55'
//   - 12 ou 13 digitos comecando com '55' -> ja esta correto
//   - Outro tamanho -> devolve o que tiver e deixa a Solides reclamar
function normalizarCelular(celular) {
  if (!celular) return null;
  const digitos = String(celular).replace(/\D/g, '');
  if (digitos.length === 10 || digitos.length === 11) return '55' + digitos;
  if ((digitos.length === 12 || digitos.length === 13) && digitos.startsWith('55')) return digitos;
  return digitos;
}

// ------------------------------------------------------------
// 1) Le os campos crus do formulario
// ------------------------------------------------------------
const entrada = $input.first().json;
const dados   = entrada && entrada.formulario;

if (!dados || typeof dados !== 'object') {
  throw new Error(
    'Payload de entrada nao contem "formulario". Garanta que este no ' +
    'esteja apos o Webhook (e do no de validacao do RH, se houver) e que ' +
    'o front esteja enviando o objeto completo: { metadata, formulario, ' +
    'documentos, dependentes }.'
  );
}

// ------------------------------------------------------------
// 2) Monta o payload no contrato da API Solides
// ------------------------------------------------------------
const cpfLimpo = String(dados.cpf || '').replace(/\D/g, '');

const colaborador = {
  // --- Dados cadastrais (obrigatorios + basicos) ---
  name:     String(dados.nome  || '').trim(),
  email:    String(dados.email || '').trim().toLowerCase(),
  cpf:      cpfLimpo,
  idNumber: cpfLimpo,  // a API duplica CPF em "idNumber"

  // --- Dados pessoais ---
  birthDate:     formatarDataBR(dados.dataNascimento),
  maritalStatus: MAPA_ESTADO_CIVIL[dados.estadoCivil] || null,
  ethnicity:     MAPA_ETNIA[dados.etnia] || null,
  motherName:    String(dados.nomeMae || '').trim(),
  birthPlace:    String(dados.cidadeNascimento || '').trim(),

  // --- Escolaridade ---
  schooling:     MAPA_GRAU_INSTRUCAO[dados.grauInstrucao] || null,

  // --- Endereco (campos achatados, conforme contrato) ---
  zipCode:        String(dados.cep || '').replace(/\D/g, ''),
  countryAcronym: 'BR',
  stateAcronym:   String(dados.estado || '').trim().toUpperCase(),
  city:           String(dados.cidade  || '').trim(),
  neighborhood:   String(dados.bairro  || '').trim(),
  streetName:     String(dados.rua     || '').trim(),
  number:         String(dados.numero  || '').trim(),

  // --- Contato (com codigo do pais: ver normalizarCelular) ---
  cellPhone: normalizarCelular(dados.celular),

  // --- Padroes uteis para HR ---
  nationality:   'Brasileiro',
  dateAdmission: formatarDataBR(new Date().toISOString().slice(0, 10))
};

// --- Opcionais (so envia se preencheu) ---
const gender = MAPA_GENERO[dados.genero];
if (gender) colaborador.gender = gender;

if (dados.nomePai && String(dados.nomePai).trim()) {
  colaborador.fatherName = String(dados.nomePai).trim();
}
if (dados.complemento && String(dados.complemento).trim()) {
  colaborador.additionalInformation = String(dados.complemento).trim();
}
if (dados.formacao && String(dados.formacao).trim()) {
  // 'course' = nome do curso/forma\u00e7\u00e3o (texto livre na API).
  colaborador.course = String(dados.formacao).trim();
}

// --- Campos profissionais (vem do no de validacao do RH) ---
if (entrada.position)   colaborador.position   = entrada.position;
if (entrada.department) colaborador.department = entrada.department;

// ------------------------------------------------------------
// 3) Sanity check dos obrigatorios pela Solides
//    Para tornar cargo/setor obrigatorios, acrescentar
//    'position' e 'department' nesta lista.
// ------------------------------------------------------------
for (const campo of ['name', 'email', 'cpf']) {
  if (!colaborador[campo] || String(colaborador[campo]).trim() === '') {
    throw new Error(`Campo obrigatorio ausente no payload Solides: ${campo}`);
  }
}

// ------------------------------------------------------------
// 4) Dispara o POST para a Solides
//    Header literal: Authorization: Token token=<TOKEN> (NAO Bearer)
// ------------------------------------------------------------
const response = await fetch(SOLIDES_ENDPOINT, {
  method: 'POST',
  headers: {
    'Authorization': `Token token=${SOLIDES_TOKEN}`,
    'Accept':        'application/json',
    'Content-Type':  'application/json'
  },
  body: JSON.stringify(colaborador)
});

// 5) Tenta parsear como JSON; cai em texto se nao for.
const textoResposta = await response.text();
let corpo;
try { corpo = JSON.parse(textoResposta); } catch { corpo = textoResposta; }

// 6) Em caso de erro HTTP, lanca com a mensagem da API se houver.
if (!response.ok) {
  const detalhe = (corpo && (corpo.message || corpo.error))
    || (Array.isArray(corpo && corpo.errors) ? corpo.errors.join(', ') : null)
    || (typeof corpo === 'string' ? corpo : null)
    || `HTTP ${response.status}`;
  throw new Error(`Solides retornou ${response.status}: ${detalhe}`);
}

// 7) Sucesso - devolve id do colaborador + corpo bruto + ecoa metadata.
return [
  {
    json: {
      ok:              true,
      status:          response.status,
      solidesId:       (corpo && corpo.id) || null,
      solidesResponse: corpo,
      metadata:        entrada.metadata || null,
      candidato: {
        nome:  colaborador.name,
        email: colaborador.email,
        cpf:   colaborador.cpf
      }
    }
  }
];
